  @protected
  void sse_encode_media_event(MediaEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MediaEvent_ConnectionState(
        serverKey: final serverKey,
        channelId: final channelId,
        state: final state,
      ):
        sse_encode_i_32(0, serializer);
        sse_encode_String(serverKey, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_box_autoadd_voice_connection_state(state, serializer);
      case MediaEvent_DeviceFellBack(
        output: final output,
        device: final device,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_bool(output, serializer);
        sse_encode_String(device, serializer);
      case MediaEvent_DeviceFailed(
        output: final output,
        message: final message,
      ):
        sse_encode_i_32(2, serializer);
        sse_encode_bool(output, serializer);
        sse_encode_String(message, serializer);
      case MediaEvent_DevicesChanged(field0: final field0):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_audio_devices(field0, serializer);
      case MediaEvent_Speaking(
        serverKey: final serverKey,
        channelId: final channelId,
        changes: final changes,
      ):
        sse_encode_i_32(4, serializer);
        sse_encode_String(serverKey, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_list_speaking_change(changes, serializer);
      case MediaEvent_InputLevel(dbfs: final dbfs):
        sse_encode_i_32(5, serializer);
        sse_encode_f_32(dbfs, serializer);
      case MediaEvent_SpeakingWhileMuted():
        sse_encode_i_32(6, serializer);
      case MediaEvent_NoiseSuppressionFellBack():
        sse_encode_i_32(7, serializer);
      case MediaEvent_HotkeyPressed(action: final action):
        sse_encode_i_32(8, serializer);
        sse_encode_hotkey_action(action, serializer);
      case MediaEvent_VideoTrackAdded(
        serverKey: final serverKey,
        channelId: final channelId,
        userId: final userId,
        trackId: final trackId,
        kind: final kind,
        textureId: final textureId,
        width: final width,
        height: final height,
      ):
        sse_encode_i_32(9, serializer);
        sse_encode_String(serverKey, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_i_64(userId, serializer);
        sse_encode_String(trackId, serializer);
        sse_encode_video_track_kind(kind, serializer);
        sse_encode_opt_box_autoadd_i_64(textureId, serializer);
        sse_encode_u_32(width, serializer);
        sse_encode_u_32(height, serializer);
      case MediaEvent_VideoTrackRemoved(
        serverKey: final serverKey,
        channelId: final channelId,
        userId: final userId,
        trackId: final trackId,
      ):
        sse_encode_i_32(10, serializer);
        sse_encode_String(serverKey, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_i_64(userId, serializer);
        sse_encode_String(trackId, serializer);
      case MediaEvent_CameraStopped(message: final message):
        sse_encode_i_32(11, serializer);
        sse_encode_String(message, serializer);
      case MediaEvent_ScreenShareStopped(message: final message):
        sse_encode_i_32(12, serializer);
        sse_encode_String(message, serializer);
      case MediaEvent_ConnectionStats(
        serverKey: final serverKey,
        channelId: final channelId,
        stats: final stats,
      ):
        sse_encode_i_32(13, serializer);
        sse_encode_String(serverKey, serializer);
        sse_encode_i_64(channelId, serializer);
        sse_encode_box_autoadd_voice_stats(stats, serializer);
      case MediaEvent_VoiceRecordLevel(level: final level):
        sse_encode_i_32(14, serializer);
        sse_encode_f_32(level, serializer);
      case MediaEvent_VoiceRecordStopped(reason: final reason):
        sse_encode_i_32(15, serializer);
        sse_encode_voice_stop_reason(reason, serializer);
      case MediaEvent_PlaybackUpdate(
        item: final item,
        positionMs: final positionMs,
        durationMs: final durationMs,
        playing: final playing,
        buffering: final buffering,
      ):
        sse_encode_i_32(16, serializer);
        sse_encode_box_autoadd_playback_item(item, serializer);
        sse_encode_u_32(positionMs, serializer);
        sse_encode_u_32(durationMs, serializer);
        sse_encode_bool(playing, serializer);
        sse_encode_bool(buffering, serializer);
      case MediaEvent_PlaybackEnded(item: final item):
        sse_encode_i_32(17, serializer);
        sse_encode_box_autoadd_playback_item(item, serializer);
      case MediaEvent_PlaybackFailed(item: final item, message: final message):
        sse_encode_i_32(18, serializer);
        sse_encode_box_autoadd_playback_item(item, serializer);
        sse_encode_String(message, serializer);
    }
  }

